service.method:

DELETE 
  FROM #DB_OWNER#SFRWK 
 WHERE PROCESS_ID    = ${PROCESS_ID} 
   AND METHOD        = ${METHOD}
   AND HOUSE_CODE    = ${session.HOUSE_CODE}


SELECT COUNT(*) CNT
  FROM #DB_OWNER#SFRWK 
 WHERE PROCESS_ID    = ${PROCESS_ID} 
   AND METHOD        = ${METHOD}
   AND SERVICE_CLASS = ${SERVICE_CLASS}
   AND HOUSE_CODE    = ${session.HOUSE_CODE}


UPDATE #DB_OWNER#SFRWK
   SET PROCESS_ID    = ${PROCESS_ID}
	  ,METHOD        = ${METHOD}
	  ,SERVICE_CLASS = ${SERVICE_CLASS}
	  ,DESCRIPTION   = ${DESCRIPTION}
 WHERE PROCESS_ID    = ${PROCESS_ID} 
   AND METHOD        = ${METHOD}
   AND SERVICE_CLASS = ${SERVICE_CLASS}
   AND HOUSE_CODE    = ${session.HOUSE_CODE}
